const records = steps.fetch_due_followups.records || [];

return records.map(record => {
  const f = record.fields;
  const touchCount = f['Touch Count'] || 0;
  const nextTouch = touchCount + 1;
  const segment = f.Segment;
  const channel = f['Preferred Channel'];
  const firstName = f.Name?.split(' ')[0] || 'there';
  const business = f.Business;
  const painPoint = f['Pain Point'];
  const leadMagnet = f['Lead Magnet'];

  let subject = '';
  let body = '';
  let whatsappText = '';
  let linkedinText = '';

  if (nextTouch === 1) {
    // Touch 1: Value delivery + soft CTA
    if (segment === 'KZN Trades/Local SMBs') {
      subject = `Quick question about ${business}`;
      body = `Hi ${firstName},\n\nSaw your note about "${painPoint}" — that's exactly why we built the "Stop Losing Quotes" blueprint.\n\nOne quick thing: the WhatsApp auto-reply + job logging setup takes 15 mins and starts catching after-hours leads tonight.\n\nWant me to send the 3-step setup checklist? Just reply YES.\n\n— Michael @ Agentcy`;
      whatsappText = `Hi ${firstName}, saw your note about "${painPoint}" — the WhatsApp auto-reply setup takes 15 mins and catches after-hours leads tonight. Want the 3-step checklist? Reply YES. — Michael @ Agentcy`;
      linkedinText = `Hi ${firstName}, quick question about ${business} — want the WhatsApp auto-reply checklist from the blueprint? Reply YES.`;
    } else if (segment === 'National Online SMBs') {
      subject = `Your 3-automation roadmap — one question`;
      body = `Hi ${firstName},\n\nYour "Find 3 Automations" roadmap should've landed. The #1 pick for ${business}: unified order → inventory → accounting sync (saves 5-8 hrs/week).\n\nQuick question: which platform hurts most right now — Takealot sync, Shopify inventory, or Xero reconciliation?\n\nReply and I'll prioritize that one in the Make blueprint.\n\n— Michael @ Agentcy`;
      whatsappText = `Hi ${firstName}, which platform hurts most — Takealot sync, Shopify inventory, or Xero reconciliation? Reply and I'll prioritize in your Make blueprint. — Michael`;
      linkedinText = `Hi ${firstName}, which platform hurts most for ${business} — Takealot, Shopify, or Xero? I'll prioritize in your roadmap.`;
    } else {
      subject = `AI Readiness Scorecard — your top gap`;
      body = `Hi ${firstName},\n\nYour scorecard highlighted ${painPoint} as the biggest friction.\n\nFor professional services, the fastest win is usually Meeting-to-CRM automation (Fathom → Make → Clio/HubSpot). 2-hour setup, 100% capture rate.\n\nWant the exact Make scenario JSON? Reply YES.\n\n— Michael @ Agentcy`;
      whatsappText = `Hi ${firstName}, your scorecard highlighted ${painPoint}. Fastest win: Meeting-to-CRM automation (2 hr setup). Want the Make scenario? Reply YES. — Michael`;
      linkedinText = `Hi ${firstName}, your top gap: ${painPoint}. Fastest win: Meeting-to-CRM automation. Want the Make scenario?`;
    }
  } else if (nextTouch === 2) {
    // Touch 2: Social proof + harder CTA
    if (segment === 'KZN Trades/Local SMBs') {
      subject = `How Punctual Plumbers recovered R187K in lost quotes`;
      body = `Hi ${firstName},\n\nPunctual Plumbers (Ballito) implemented the quote follow-up sequence from the blueprint.\n\nMonth 1 result: R187K in previously-lost quotes recovered. The "Day 3: quote expiring Friday" message was the killer.\n\nIf you want that exact Make scenario imported into your account, book a 15-min screen-share:\nhttps://calendly.com/agentcy/30min-strategy\n\n— Michael`;
      whatsappText = `Hi ${firstName}, Punctual Plumbers recovered R187K in lost quotes using the blueprint's follow-up sequence. Want the Make template? Book 15-min: https://calendly.com/agentcy/30min-strategy`;
      linkedinText = `Hi ${firstName}, Punctual Plumbers recovered R187K with the quote follow-up sequence. Want the Make template? https://calendly.com/agentcy/30min-strategy`;
    } else if (segment === 'National Online SMBs') {
      subject = `Sarah's Homewares: 11 hrs/week back in 3 days`;
      body = `Hi ${firstName},\n\nSarah (Cape Town, Shopify + Takealot) plugged in the order→inventory→Xero sync.\n\nDay 1: 6.5 hrs saved. Day 3: zero oversells. Month 1: +R340K revenue from faster fulfillment → better reviews.\n\nSame stack? Want the Make template?\nhttps://calendly.com/agentcy/30min-strategy\n\n— Michael`;
      whatsappText = `Hi ${firstName}, Sarah saved 11 hrs/week with order→inventory→Xero sync. Want the Make template? https://calendly.com/agentcy/30min-strategy`;
      linkedinText = `Hi ${firstName}, Sarah's Homewares saved 11 hrs/week with the order→inventory→Xero sync. Want the template? https://calendly.com/agentcy/30min-strategy`;
    } else {
      subject = `Naidoo & Associates: 47 hrs/month recovered per partner`;
      body = `Hi ${firstName},\n\nNaidoo & Associates (Commercial Law, Durban) scored 31/100 on readiness. 90 days later: 67/100.\n\nTop win: Smart Intake Form (Tally → DocuSign → Clio → Slack). Onboarding 21 days → 4 days.\n\nWant the blueprint for your practice?\nhttps://calendly.com/agentcy/30min-strategy\n\n— Michael`;
      whatsappText = `Hi ${firstName}, Naidoo & Associates recovered 47 hrs/month/partner with Smart Intake Form. Want the blueprint? https://calendly.com/agentcy/30min-strategy`;
      linkedinText = `Hi ${firstName}, Naidoo & Associates recovered 47 hrs/month with Smart Intake Form. Want the blueprint? https://calendly.com/agentcy/30min-strategy`;
    }
  } else {
    // Touch 3: Final nudge + opt-out
    subject = `Closing this thread — but the blueprint's yours`;
    body = `Hi ${firstName},\n\nI'll stop following up after this. The ${leadMagnet} blueprint is yours to keep — no strings.\n\nIf automation becomes a priority later, the 30-min strategy call is always free:\nhttps://calendly.com/agentcy/30min-strategy\n\nJust reply STOP if you want zero further contact (POPIA compliant).\n\nAll the best,\nMichael @ Agentcy`;
    whatsappText = `Hi ${firstName}, final follow-up. The ${leadMagnet} blueprint is yours. Free 30-min call always available: https://calendly.com/agentcy/30min-strategy. Reply STOP to opt out.`;
    linkedinText = `Hi ${firstName}, final note. Blueprint's yours. Free call: https://calendly.com/agentcy/30min-strategy. Reply STOP to opt out.`;
  }

  return {
    recordId: record.id,
    email: f.Email || '',
    phone: f.Phone || '',
    linkedinId: f['LinkedIn ID'] || '',
    channel,
    touchNumber: nextTouch,
    subject,
    body,
    whatsappText,
    linkedinText,
    nextFollowUpDate: new Date(Date.now() + (nextTouch === 3 ? 30 : 3) * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    lastTouchDate: new Date().toISOString().split('T')[0],
    newStatus: nextTouch >= 3 ? 'Paused' : 'Contacted'
  };
});

// This step uses Pipedream's built-in actions via $send.*
// We'll route in the next steps based on channel
return steps.process_each;
